//! Easy vocabulary (YÖN-3 K1, T-130): one easy English name per kit operation, generated by the
//! rules of `docs/meclis/yon3/dil/D3-SOZLUK.md` §2 (R1–R12 plus the namespace rule, and the two
//! extra rules D3 proposed: R13 "subject in a later parameter", R14 "writes reg0").
//!
//! Nothing here is typed by hand. The output is data the compiler and the editor read:
//! `kit-meta/easy/ops.json` (one record per operation) and `kit-meta/easy/manual.toml` (the
//! operations no rule can name yet, with an empty `easy` name — never invented).
//!
//! [KARAR-DIL](../../docs/meclis/yon3/dil/KARAR-DIL.md) §2: one name per concept. A getter and a
//! setter of the same property therefore share one `easy` name and are told apart by [`Kind`].

mod header;

pub use header::atlas_from_header;

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;

use serde::{Deserialize, Serialize};
use uw_atlas::{Atlas, Op};

/// What an operation is, now that its name is easy.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Kind {
    /// `x = subject.field` (`agent.position`).
    PropertyGet,
    /// `subject.field = x` (`agent.speed_modifier`).
    PropertySet,
    /// `if subject.thing:` (`key.is_down`).
    Condition,
    /// `subject.verb(...)`, no value back.
    Method,
    /// `x = subject.verb(...)`, one value back.
    Function,
    /// `...` control flow (`flow.try_begin`).
    Flow,
    /// `text.*` — a string built or stored (`text.store_troop_name`).
    Text,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::PropertyGet => "property_get",
            Kind::PropertySet => "property_set",
            Kind::Condition => "condition",
            Kind::Method => "method",
            Kind::Function => "function",
            Kind::Flow => "flow",
            Kind::Text => "text",
        }
    }
}

/// One operation the rules could name.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Record {
    /// The easy name; a getter and its setter share it.
    pub easy: String,
    /// The kit operation this record names.
    pub native: String,
    /// The operation code (`ge` 30, `assign` 2133, ...).
    pub code: u64,
    pub kind: Kind,
    /// The type the name belongs to (`agent`, `party`, `game`, ...).
    pub subject: String,
    /// The parameter names of the kit signature, in order.
    pub params: Vec<String>,
    /// The D3 rule that produced the name (`R1`, `R1b`, ..., `N1`, `R13`, `R14`).
    pub rule: String,
    /// The kit signature and comment (`header_operations.py`).
    pub doc: String,
    /// Line of `header_operations.py` when the atlas has one.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub line: Option<u32>,
}

/// An operation with no easy name yet: a TODO in `kit-meta/easy/manual.toml`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Manual {
    pub native: String,
    pub code: u64,
    /// What it would be if it had a name (from its flags), so the editor can place it.
    pub kind: Kind,
    /// Why it is here: empty = no rule fits; otherwise a name clash that left it unnamed.
    #[serde(skip_serializing_if = "String::is_empty")]
    pub note: String,
    pub doc: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub line: Option<u32>,
}

/// Two operations that the rules gave one name; the first (by rule priority, then code) keeps it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Clash {
    pub easy: String,
    pub kind: Kind,
    pub kept: String,
    pub dropped: Vec<String>,
}

/// The whole vocabulary: what was named, what could not be, and the name clashes met on the way.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Report {
    pub records: Vec<Record>,
    pub manual: Vec<Manual>,
    pub clashes: Vec<Clash>,
}

impl Report {
    /// Names every operation of `atlas` by the D3 rules and resolves clashes (one name per concept).
    pub fn generate(atlas: &Atlas) -> Report {
        let mut found = Vec::new();
        let mut manual = Vec::new();
        for op in &atlas.ops {
            match name_op(op) {
                Some(mut record) => {
                    if record.kind == Kind::Method && mentions_reg0(&op.signature) {
                        // R14: the comment says the value comes back in reg0.
                        record.kind = Kind::Function;
                        record.rule = "R14".to_string();
                    }
                    found.push(record);
                }
                None => match name_reg0(op) {
                    Some(record) => found.push(record),
                    None => manual.push(unnamed(op, String::new())),
                },
            }
        }
        let mut groups: BTreeMap<(String, Kind), Vec<Record>> = BTreeMap::new();
        for record in found {
            groups.entry((record.easy.clone(), record.kind)).or_default().push(record);
        }
        let mut records = Vec::new();
        let mut clashes = Vec::new();
        for ((easy, kind), mut group) in groups {
            group.sort_by(|a, b| {
                rule_rank(&a.rule).cmp(&rule_rank(&b.rule)).then(a.code.cmp(&b.code)).then(a.native.cmp(&b.native))
            });
            let winner = group.remove(0);
            if !group.is_empty() {
                for loser in &group {
                    let note = format!("name clash: `{easy}` ({}) names {} too", kind.as_str(), winner.native);
                    manual.push(Manual {
                        native: loser.native.clone(),
                        code: loser.code,
                        kind: loser.kind,
                        note,
                        doc: loser.doc.clone(),
                        line: loser.line,
                    });
                }
                clashes.push(Clash {
                    easy,
                    kind,
                    kept: winner.native.clone(),
                    dropped: group.iter().map(|record| record.native.clone()).collect(),
                });
            }
            records.push(winner);
        }
        records.sort_by(|a, b| a.code.cmp(&b.code).then(a.native.cmp(&b.native)));
        manual.sort_by(|a, b| a.code.cmp(&b.code).then(a.native.cmp(&b.native)));
        Report { records, manual, clashes }
    }

    /// How many operations got a name by rule.
    pub fn auto(&self) -> usize {
        self.records.len()
    }

    /// How many operations are still a TODO in `manual.toml`.
    pub fn manual_count(&self) -> usize {
        self.manual.len()
    }

    /// `kit-meta/easy/ops.json`: schema, provenance, counts and one record per named operation.
    pub fn ops_json(&self) -> String {
        #[derive(Serialize)]
        struct OpsFile<'a> {
            schema: u32,
            generated: &'static str,
            auto: usize,
            manual: usize,
            clashes: usize,
            ops: &'a [Record],
            clash_groups: &'a [Clash],
        }
        let file = OpsFile {
            schema: 1,
            generated: "GENERATED by `uw easy` from the kit atlas — do not edit by hand; \
                        the rules are in docs/meclis/yon3/dil/D3-SOZLUK.md §2",
            auto: self.records.len(),
            manual: self.manual.len(),
            clashes: self.clashes.len(),
            ops: &self.records,
            clash_groups: &self.clashes,
        };
        let mut out = Vec::new();
        let mut serializer =
            serde_json::Serializer::with_formatter(&mut out, serde_json::ser::PrettyFormatter::with_indent(b" "));
        file.serialize(&mut serializer).expect("the vocabulary is plain data");
        String::from_utf8(out).expect("serde_json writes UTF-8")
    }

    /// `kit-meta/easy/manual.toml`; `easy` names already filled in by hand are kept (`existing`).
    pub fn manual_toml(&self, existing: &BTreeMap<String, String>) -> String {
        let mut out = String::from(
            "# GENERATED by `uw easy` from the kit — do not edit the other fields by hand.\n\
             # Every operation no rule can name yet, one TODO per entry: fill `easy` (empty = TODO).\n\
             # Rules and the one-name-per-concept decision: docs/meclis/yon3/dil/D3-SOZLUK.md,\n\
             # docs/meclis/yon3/dil/KARAR-DIL.md. Never invent a native name.\n",
        );
        for entry in &self.manual {
            out.push_str("\n[[op]]\n");
            let easy = existing.get(&entry.native).map(String::as_str).unwrap_or("");
            let _ = writeln!(out, "easy = {}", toml_string(easy));
            let _ = writeln!(out, "native = {}", toml_string(&entry.native));
            let _ = writeln!(out, "kind = {}", toml_string(entry.kind.as_str()));
            let _ = writeln!(out, "code = {}", entry.code);
            if let Some(line) = entry.line {
                let _ = writeln!(out, "line = {line}");
            }
            if !entry.note.is_empty() {
                let _ = writeln!(out, "note = {}", toml_string(&entry.note));
            }
            let _ = writeln!(out, "doc = {}", toml_string(&entry.doc));
        }
        out
    }

    /// Writes both files into `dir`, keeping hand-filled `easy` names of an existing `manual.toml`.
    pub fn write(&self, dir: &Path) -> std::io::Result<()> {
        std::fs::create_dir_all(dir)?;
        std::fs::write(dir.join("ops.json"), self.ops_json())?;
        let existing = std::fs::read_to_string(dir.join("manual.toml"))
            .map(|text| manual_easy(&text))
            .unwrap_or_default();
        std::fs::write(dir.join("manual.toml"), self.manual_toml(&existing))?;
        Ok(())
    }
}

/// The `native -> easy` pairs of an existing `manual.toml` (the hand-filled names survive a run).
fn manual_easy(text: &str) -> BTreeMap<String, String> {
    let mut easy = BTreeMap::new();
    let mut native = None;
    for line in text.lines() {
        let Some((key, value)) = line.split_once('=') else { continue };
        let value = value.trim().trim_matches('"').to_string();
        match key.trim() {
            "native" => native = Some(value),
            "easy" if !value.is_empty() => {
                if let Some(native) = &native {
                    easy.insert(native.clone(), value);
                }
            }
            _ => {}
        }
    }
    easy
}

fn toml_string(text: &str) -> String {
    let mut out = String::from("\"");
    for ch in text.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ch if (ch as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", ch as u32);
            }
            ch => out.push(ch),
        }
    }
    out.push('"');
    out
}

fn unnamed(op: &Op, note: String) -> Manual {
    let kind = if op.can_fail {
        Kind::Condition
    } else if op.lhs {
        Kind::PropertyGet
    } else {
        Kind::Function
    };
    Manual { native: op.name.clone(), code: op.code, kind, note, doc: op.signature.clone(), line: op.line }
}

fn rule_rank(rule: &str) -> u8 {
    match rule {
        "R1" => 1,
        "R1b" => 2,
        "R1c" => 3,
        "R2" => 4,
        "R3" => 5,
        "R4" => 6,
        "R5" => 7,
        "R6" => 8,
        "R7" => 9,
        "R8" => 10,
        "R9" => 11,
        "R10" => 12,
        "R11" => 13,
        "R12" => 14,
        "N1" => 15,
        "R13" => 16,
        "R14" => 17,
        _ => 99,
    }
}

