/// The arithmetic family of R9 (`store_add` → `math.add`).
const ARITHMETIC: [&str; 11] = [
    "store_add",
    "store_sub",
    "store_mul",
    "store_div",
    "store_mod",
    "store_min",
    "store_max",
    "store_pow",
    "store_random",
    "store_random_in_range",
    "store_sqrt",
];

fn rec(op: &Op, rule: &str, kind: Kind, subject: &str, easy: String, params: Vec<String>) -> Record {
    Record {
        easy,
        native: op.name.clone(),
        code: op.code,
        kind,
        subject: subject.to_string(),
        params,
        rule: rule.to_string(),
        doc: op.signature.clone(),
        line: op.line,
    }
}

fn name_op(op: &Op) -> Option<Record> {
    let params = signature_params(&op.signature, &op.name);
    let name = op.name.as_str();
    // R11: control flow keeps its own group.
    if name.starts_with("try_") || matches!(name, "end_try" | "else_try" | "else_try_begin") {
        return Some(rec(op, "R11", Kind::Flow, "flow", format!("flow.{name}"), params));
    }
    // R10: the comparisons are conditions on two values.
    if matches!(name, "ge" | "eq" | "gt" | "lt" | "neq" | "le" | "is_between") {
        return Some(rec(op, "R10", Kind::Condition, "value", format!("value.{name}"), params));
    }
    // R9: arithmetic, always a number (never a hand-named set of operations).
    if name == "assign" {
        return Some(rec(op, "R9", Kind::Function, "value", "value.assign".to_string(), params));
    }
    if let Some(rest) = name.strip_prefix("val_") {
        return Some(rec(op, "R9", Kind::Method, "value", format!("value.{rest}"), params));
    }
    if ARITHMETIC.contains(&name) {
        return Some(rec(op, "R9", Kind::Function, "number", format!("math.{}", &name[6..]), params));
    }
    // R12: text (str_* build or read a string).
    if let Some(rest) = name.strip_prefix("str_") {
        return Some(rec(op, "R12", Kind::Text, "text", format!("text.{rest}"), params));
    }
    // R1c: `store_<subject>_<field>` — the kit's name for a getter when reg0 is not used.
    if let Some(rest) = name.strip_prefix("store_") {
        if op.lhs {
            if let Some((subject, field)) = subject_prefix(rest) {
                return Some(rec(op, "R1c", Kind::PropertyGet, subject, format!("{subject}.{field}"), params));
            }
        }
    }
    // R1–R5: the subject is in the operation's own name.
    if let Some((subject, rest)) = subject_prefix(name) {
        if rest == "get_slot" && op.lhs {
            return Some(rec(op, "R5", Kind::PropertyGet, subject, format!("{subject}.slot"), params));
        }
        if rest == "set_slot" && !op.lhs {
            return Some(rec(op, "R5", Kind::PropertySet, subject, format!("{subject}.slot"), params));
        }
        if let Some(field) = rest.strip_prefix("get_") {
            let rule = if returns_destination(&params) {
                "R1"
            } else if returns_position(&params) {
                "R1b"
            } else if params.iter().skip(1).any(|param| type_of(param) == Some(subject)) {
                // R13: the subject is a later parameter (`faction_get_color(c, f)`).
                "R13"
            } else if op.lhs {
                // R13: the return slot has a kit name of its own (`<value>`, `<color>`).
                "R13"
            } else {
                "R1"
            };
            return Some(rec(op, rule, Kind::PropertyGet, subject, format!("{subject}.{field}"), params));
        }
        if let Some(field) = rest.strip_prefix("set_") {
            if !op.lhs {
                return Some(rec(op, "R2", Kind::PropertySet, subject, format!("{subject}.{field}"), params));
            }
        }
        if op.can_fail && !op.lhs {
            return Some(rec(op, "R3", Kind::Condition, subject, format!("{subject}.{rest}"), params));
        }
        if !op.lhs {
            return Some(rec(op, "R4", Kind::Method, subject, format!("{subject}.{rest}"), params));
        }
    }
    // R13: the subject is the first entity parameter, wherever it sits.
    if let Some(record) = subject_in_params(op, &params) {
        return Some(record);
    }
    // N1: a verb prefix on a global operation is a namespace.
    if let Some((namespace, rest)) = namespace(name) {
        if let Some(field) = rest.strip_prefix("get_") {
            return Some(rec(op, "N1", Kind::PropertyGet, namespace, format!("{namespace}.{field}"), params));
        }
        if let Some(field) = rest.strip_prefix("set_") {
            return Some(rec(op, "N1", Kind::PropertySet, namespace, format!("{namespace}.{field}"), params));
        }
        if name.starts_with("create_") && name.ends_with("_overlay") {
            return Some(rec(op, "N1", Kind::Function, namespace, format!("{namespace}.{rest}"), params));
        }
        let kind = if op.can_fail && !op.lhs { Kind::Condition } else { Kind::Method };
        return Some(rec(op, "N1", kind, namespace, format!("{namespace}.{rest}"), params));
    }
    // R6: a global getter/store (the value goes to `destination` or reg0).
    if let Some(rest) = name.strip_prefix("get_") {
        if op.lhs {
            return Some(rec(op, "R6", Kind::PropertyGet, "game", format!("game.{rest}"), params));
        }
    }
    if let Some(rest) = name.strip_prefix("store_") {
        if op.lhs {
            return Some(rec(op, "R6", Kind::PropertyGet, "game", format!("game.{rest}"), params));
        }
    }
    // R7: a global setter.
    if let Some(rest) = name.strip_prefix("set_") {
        if !op.lhs {
            return Some(rec(op, "R7", Kind::PropertySet, "game", format!("game.{rest}"), params));
        }
    }
    // R8: a global condition.
    if op.can_fail && !op.lhs {
        return Some(rec(op, "R8", Kind::Condition, "game", format!("game.{name}"), params));
    }
    None
}

/// R13: subject from the first entity parameter (the return slot of a getter is skipped).
fn subject_in_params(op: &Op, params: &[String]) -> Option<Record> {
    let start = usize::from(op.lhs);
    let subject = params.iter().skip(start).find_map(|param| type_of(param))?;
    let field = field_of(&op.name, subject)?;
    let (kind, field) = match field.strip_prefix("get_") {
        Some(field) => (Kind::PropertyGet, field),
        None => match field.strip_prefix("set_") {
            Some(field) => (Kind::PropertySet, field),
            None => {
                if op.can_fail && !op.lhs {
                    (Kind::Condition, field.as_str())
                } else {
                    (Kind::Method, field.as_str())
                }
            }
        },
    };
    Some(rec(op, "R13", kind, subject, format!("{subject}.{field}"), params.to_vec()))
}

/// R14: the comment says a value arrives in reg0, so the operation is a function.
fn name_reg0(op: &Op) -> Option<Record> {
    if !mentions_reg0(&op.signature) {
        return None;
    }
    // "stores agent_id in reg0" names the type of the value that comes back: the parameter named
    // closest before reg0 wins, unless the operation's own name already says it.
    let before = match op.signature.find("reg0") {
        Some(at) => &op.signature[..at],
        None => op.signature.as_str(),
    };
    let from_reg0 = PARAM_TYPES.iter().filter(|(param, _)| before.contains(param)).last().map(|(_, ty)| *ty);
    let from_name =
        PARAM_TYPES.iter().find(|(_, ty)| words_of(ty).iter().any(|word| op.name.contains(word))).map(|(_, ty)| *ty);
    let subject = from_name.or(from_reg0)?;
    let field = field_of(&op.name, subject).unwrap_or_else(|| op.name.clone());
    let params = signature_params(&op.signature, &op.name);
    Some(rec(op, "R14", Kind::Function, subject, format!("{subject}.{field}"), params))
}

fn mentions_reg0(doc: &str) -> bool {
    doc.contains("reg0") || doc.contains("reg(0")
}

/// The field part of a name, given the subject word: `check_quest_active` → `active`,
/// `add_xp_to_troop` → `add_xp` (a dangling preposition is dropped).
fn field_of(name: &str, subject: &str) -> Option<String> {
    for word in words_of(subject) {
        if let Some(rest) = name.strip_prefix(&format!("check_{word}_")) {
            return Some(rest.to_string());
        }
        if let Some(rest) = name.strip_prefix(&format!("{word}_")) {
            return Some(rest.to_string());
        }
        if let Some(rest) = name.strip_suffix(&format!("_{word}")) {
            return Some(trim_preposition(rest).to_string());
        }
    }
    None
}

fn trim_preposition(text: &str) -> &str {
    let mut text = text;
    while let Some((head, tail)) = text.rsplit_once('_') {
        if matches!(tail, "to" | "from" | "of" | "for" | "in" | "with" | "on") {
            text = head;
        } else {
            break;
        }
    }
    text
}

/// The kit words that name a subject type (longest first).
fn words_of(subject: &str) -> Vec<&str> {
    let mut words: Vec<&str> = SUBJECTS.iter().filter(|(_, ty)| *ty == subject).map(|(word, _)| *word).collect();
    words.sort_by_key(|word| std::cmp::Reverse(word.len()));
    words
}

fn subject_prefix(text: &str) -> Option<(&str, &str)> {
    SUBJECTS
        .iter()
        .find_map(|(word, subject)| text.strip_prefix(word).and_then(|rest| rest.strip_prefix('_')).map(|rest| (*subject, rest)))
}

fn namespace(name: &str) -> Option<(&str, &str)> {
    if let Some(middle) = name.strip_prefix("create_").and_then(|rest| rest.strip_suffix("_overlay")) {
        if !middle.is_empty() {
            return Some(("ui", middle));
        }
    }
    NAMESPACES
        .iter()
        .find_map(|(word, namespace)| name.strip_prefix(word).and_then(|rest| rest.strip_prefix('_')).map(|rest| (*namespace, rest)))
}

fn type_of(param: &str) -> Option<&'static str> {
    PARAM_TYPES.iter().find(|(name, _)| name.eq_ignore_ascii_case(param)).map(|(_, ty)| *ty)
}

fn returns_position(params: &[String]) -> bool {
    params.first().and_then(|param| type_of(param)) == Some("pos")
}

fn returns_destination(params: &[String]) -> bool {
    params.first().map_or(true, |param| param == "destination")
}

/// The parameter names of a kit signature: `(agent_set_speed_modifier, <agent_id>, <value>)` →
/// `agent_id`, `value`. Signatures that are only prose give no parameters.
pub fn signature_params(signature: &str, op: &str) -> Vec<String> {
    let op = op.to_ascii_lowercase();
    let mut start = None;
    for (index, _) in signature.match_indices('(') {
        let inner = signature[index + 1..].trim_start();
        if inner.to_ascii_lowercase().starts_with(&op) {
            let after = inner[op.len()..].trim_start();
            if after.starts_with(',') || after.starts_with(')') {
                start = Some(index);
                break;
            }
        }
    }
    let start = match start.or_else(|| signature.find('(')) {
        Some(start) => start,
        None => return Vec::new(),
    };
    let end = match signature[start + 1..].find(')') {
        Some(end) => start + 1 + end,
        None => return Vec::new(),
    };
    signature[start + 1..end]
        .split(',')
        .map(clean_param)
        .filter(|param| !param.is_empty())
        .skip_while(|param| param.eq_ignore_ascii_case(&op))
        .collect()
}

fn clean_param(param: &str) -> String {
    param.trim().trim_matches(|ch: char| matches!(ch, '<' | '>' | '[' | ']' | '(' | ')' | ' ' | ',' | '.')).to_string()
}
